import { useCallback, useEffect, useState } from 'react'
import Workspace from './components/Workspace.jsx'
import { createItem, deleteItem, listItems, updateItem } from './api.js'

export default function App() {
  const [items, setItems] = useState([]), [error, setError] = useState(''), [online, setOnline] = useState(false)
  const refresh = useCallback(async () => { try { const data = await listItems(); setItems(data); setOnline(true); setError('') } catch (reason) { setOnline(false); setError(reason.message) } }, [])
  useEffect(() => { refresh() }, [refresh])
  const act = async action => { try { await action(); await refresh() } catch (reason) { setError(reason.message) } }
  return <main className="app"><nav><div className="brand"><span>✦</span>{"Legacy Acceptance"}</div><span className={online ? 'status online' : 'status'}><i />{online ? 'Application connected' : 'Connecting…'}</span></nav><section className="hero"><div><small>A FOCUSED PRODUCT WORKSPACE</small><h1>Move good work<br/>forward, together.</h1><p>{"Preserve a legacy package."}</p></div><aside><small>LIVE APPLICATION DATA</small><strong>{items.filter(x => x.completed).length} / {items.length}</strong><span>priorities completed</span></aside></section>{error && <div className="error">{error}</div>}<Workspace items={items} canEdit={false} onRefresh={refresh} onAdd={title => act(() => createItem(title))} onToggle={item => act(() => updateItem(item))} onDelete={item => act(() => deleteItem(item))}/></main>
}

